export function script(input) {
  const raw = String(input.domain || '').trim();
  const candidate = raw.replace(/^[a-z][a-z0-9+.-]*:\/\//i, '').split(/[/?#]/, 1)[0].replace(/:\d+$/, '').replace(/\.+$/, '').replace(/^www\./i, '').toLowerCase();
  const labels = candidate.split('.');
  const validDomain = candidate.length <= 253 && labels.length >= 2 && labels.every((label) => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i.test(label));
  const queryDomain = validDomain ? candidate : 'invalid.invalid';
  const dohUrl = (name, type) => `https://dns.google/resolve?name=${encodeURIComponent(name)}&type=${type}`;
  return { domain: validDomain ? candidate : '', validDomain, rootTxtUrl: dohUrl(queryDomain, 'TXT'), dmarcTxtUrl: dohUrl(`_dmarc.${queryDomain}`, 'TXT'), mxUrl: dohUrl(queryDomain, 'MX') };
}

export function script(input) {
  const answersFor = (data) => Array.isArray(data?.Answer) ? data.Answer : [];
  const unquote = (value) => String(value || '').replace(/^\"|\"$/g, '').replace(/\"\s*\"/g, '');
  const rootAnswers = answersFor(input.rootData);
  const dmarcAnswers = answersFor(input.dmarcData);
  const mxAnswers = answersFor(input.mxData);
  const spfRecords = rootAnswers.filter(
    (answer) => answer.type === 16 && /^v=spf1\b/i.test(unquote(answer.data)),
  );
  const dmarcRecords = dmarcAnswers.filter(
    (answer) => answer.type === 16 && /^v=dmarc1\b/i.test(unquote(answer.data)),
  );
  const mxRecords = mxAnswers.filter((answer) => answer.type === 15);
  const source = (data, status, statusText) => {
    const statusNumber = Number(status || 0);
    const ok = statusNumber >= 200 && statusNumber < 300;
    const hasBody = Boolean(data && typeof data === 'object' && !Array.isArray(data) && Object.keys(data).length > 0);
    return { status: statusNumber, statusText: statusText || null, ok, usable: ok && hasBody };
  };
  const sources = {
    rootTxt: source(input.rootData, input.rootStatus, input.rootStatusText),
    dmarcTxt: source(input.dmarcData, input.dmarcStatus, input.dmarcStatusText),
    mx: source(input.mxData, input.mxStatus, input.mxStatusText)
  };
  const warnings = [];
  const findings = [];
  if (!input.validDomain) warnings.push('The supplied domain was empty or invalid; DNS requests were routed to invalid.invalid.');
  for (const [name, value] of Object.entries(sources)) {
    if (!value.usable) warnings.push(`${name} lookup has no usable DNS evidence: ${value.statusText || value.status || 'no response body'}`);
  }
  if (sources.rootTxt.usable && spfRecords.length === 0) findings.push({ severity: 'high', title: 'No SPF record observed', evidence: 'No root TXT record started with v=spf1.' });
  if (sources.rootTxt.usable && spfRecords.length > 1) findings.push({ severity: 'medium', title: 'Multiple SPF records observed', evidence: `Observed ${spfRecords.length} TXT records starting with v=spf1.` });
  if (sources.dmarcTxt.usable && dmarcRecords.length === 0) findings.push({ severity: 'high', title: 'No DMARC record observed', evidence: 'No _dmarc TXT record started with v=DMARC1.' });
  const dmarcText = dmarcRecords.map((answer) => unquote(answer.data)).join('; ');
  if (sources.dmarcTxt.usable && /\bp\s*=\s*none\b/i.test(dmarcText)) findings.push({ severity: 'medium', title: 'DMARC policy is monitoring-only', evidence: 'Observed p=none in a DMARC record.' });
  const pctMatch = dmarcText.match(/\bpct\s*=\s*(\d+)/i);
  if (sources.dmarcTxt.usable && pctMatch && Number(pctMatch[1]) < 100) findings.push({ severity: 'medium', title: 'DMARC enforcement is partial', evidence: `Observed pct=${pctMatch[1]}.` });
  if (sources.mx.usable && mxRecords.length === 0) findings.push({ severity: 'medium', title: 'No MX records observed', evidence: 'No MX records were returned by the public resolver.' });
  return { report: { summary: { domain: input.domain || null, findings: findings.length, spfRecordCount: spfRecords.length, dmarcRecordCount: dmarcRecords.length, mxRecordCount: mxRecords.length }, findings, warnings, sourceStatuses: sources, observedRecords: { spf: spfRecords.map((answer) => unquote(answer.data)), dmarc: dmarcRecords.map((answer) => unquote(answer.data)), mx: mxRecords.map((answer) => unquote(answer.data)) }, authorizationNotes: input.authorizationNotes || null, nextSteps: ['Publish exactly one syntactically valid SPF record when mail is sent for this domain', 'Publish a DMARC record and move from monitoring to an enforcement policy after alignment is validated', 'Set DMARC pct=100 once the enforcement rollout is complete', 'Verify MX records match the intended mail-receiving service', 'Review DKIM separately; this DNS-only workflow does not claim DKIM coverage'] } };
}
